import 'package:flutter/material.dart';import '../core/utils/formatters.dart';import '../data/repositories/expense_repository.dart';
class AccountsScreen extends StatefulWidget{const AccountsScreen({super.key,required this.onChanged});final VoidCallback onChanged;@override State<AccountsScreen> createState()=>_AccountsScreenState();}
class _AccountsScreenState extends State<AccountsScreen>{final repo=ExpenseRepository();late Future<List<Map<String,Object?>>> future;@override void initState(){super.initState();future=repo.accounts();}void reload()=>setState(()=>future=repo.accounts());
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Accounts')),body:FutureBuilder<List<Map<String,Object?>>>(future:future,builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(padding:const EdgeInsets.all(16),children:[...s.data!.map((e)=>FutureBuilder<int>(future:repo.balance(e['id'] as int,e['opening_minor'] as int),builder:(c,b)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.account_balance_wallet)),title:Text(e['name'] as String),subtitle:Text(e['type'] as String),trailing:Text(Fmt.money((b.data??0)/100),style:const TextStyle(fontWeight:FontWeight.bold))))))]);}),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add account')));
 Future<void> add()async{final name=TextEditingController(),amount=TextEditingController(text:'0');String type='cash';final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('New account'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),DropdownButtonFormField<String>(value:type,items:const[DropdownMenuItem(value:'cash',child:Text('Cash')),DropdownMenuItem(value:'bank',child:Text('Bank')),DropdownMenuItem(value:'wallet',child:Text('Wallet')),DropdownMenuItem(value:'credit',child:Text('Credit card'))],onChanged:(v)=>setD(()=>type=v!)),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Opening balance'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));if(ok==true&&name.text.trim().isNotEmpty){await repo.addAccount(name.text.trim(),type,((double.tryParse(amount.text)??0)*100).round());widget.onChanged();reload();}name.dispose();amount.dispose();}
}
